@@ -0,0 +1,170 @@
+// Expense Tracker Module
+
+import { freeze } from 'node:util';
+
+export function createExpenseTracker(filePath) {
+  let expenses = [];
+
+  const loadExpenses = async () => {
+    try {
+      const data = await Deno.readTextFile(filePath);
+      expenses = JSON.parse(data);
+    } catch (error) {
+      if (error.code !== 'ENOENT') {
+        throw error;
+      }
+    }
+  };
+
+  const saveExpenses = async () => {
+    await Deno.writeTextFile(filePath, JSON.stringify(expenses, null, 2));
+  };
+
+  const validateExpense = (expense) => {
+    if (!expense.id || typeof expense.id !== 'string' || expense.id.trim() === '') {
+      throw new Error('INVALID_EXPENSE');
+    }
+
+    if (typeof expense.amount !== 'number' || isNaN(expense.amount) || expense.amount <= 0) {
+      throw new Error('INVALID_EXPENSE');
+    }
+
+    if (typeof expense.currency !== 'string' || expense.currency.length !== 3 || !/^[A-Z]{3}$/.test(expense.currency)) {
+      throw new Error('INVALID_EXPENSE');
+    }
+
+    if (typeof expense.category !== 'string' || expense.category.trim() === '') {
+      throw new Error('INVALID_EXPENSE');
+    }
+
+    if (typeof expense.date !== 'string' || !/\d{4}-\d{2}-\d{2}$/.test(expense.date)) {
+      throw new Error('INVALID_EXPENSE');
+    }
+
+    if (typeof expense.note !== 'string') {
+      throw new Error('INVALID_EXPENSE');
+    }
+
+    if (expenses.some(e => e.id === expense.id)) {
+      throw new Error('DUPLICATE_ID');
+    }
+  };
+
+  const addExpense = async (expense) => {
+    validateExpense(expense);
+    expenses.push(expense);
+    await saveExpenses();
+  };
+
+  const updateExpense = async (id, update) => {
+    const expense = expenses.find(e => e.id === id);
+    if (!expense) {
+      throw new Error('NOT_FOUND');
+    }
+
+    const allowedFields = ['amount', 'currency', 'category', 'date', 'note'];
+    const patchFields = Object.keys(update).filter(field => allowedFields.includes(field));
+
+    if (patchFields.length === 0) {
+      throw new Error('INVALID_PATCH');
+    }
+
+    for (const field of patchFields) {
+      if (field === 'amount') {
+        if (typeof update[field] !== 'number' || isNaN(update[field]) || update[field] <= 0) {
+          throw new Error('INVALID_PATCH');
+        }
+      } else if (field === 'currency') {
+        if (typeof update[field] !== 'string' || update[field].length !== 3 || !/^[A-Z]{3}$/.test(update[field])) {
+          throw new Error('INVALID_PATCH');
+        }
+      } else if (field === 'category') {
+        if (typeof update[field] !== 'string' || update[field].trim() === '') {
+          throw new Error('INVALID_PATCH');
+        }
+      } else if (field === 'date') {
+        if (typeof update[field] !== 'string' || !/\d{4}-\d{2}-\d{2}$/.test(update[field])) {
+          throw new Error('INVALID_PATCH');
+        }
+      } else if (field === 'note') {
+        if (typeof update[field] !== 'string') {
+          throw new Error('INVALID_PATCH');
+        }
+      }
+
+      expense[field] = update[field];
+    }
+
+    await saveExpenses();
+  };
+
+  const removeExpense = async (id) => {
+    const expense = expenses.find(e => e.id === id);
+    if (!expense) {
+      throw new Error('NOT_FOUND');
+    }
+
+    const index = expenses.indexOf(expense);
+    const removed = expenses.splice(index, 1);
+    await saveExpenses();
+    return removed[0];
+  };
+
+  const listExpenses = () => {
+    return [...expenses];
+  };
+
+  const getExpense = (id) => {
+    return expenses.find(e => e.id === id) || undefined;
+  };
+
+  const summary = () => {
+    const totalByCurrency = {};
+    const totalByCategory = {};
+
+    for (const expense of expenses) {
+      const { currency, category, amount } = expense;
+
+      if (!totalByCurrency[currency]) {
+        totalByCurrency[currency] = 0;
+      }
+      totalByCurrency[currency] += amount;
+
+      if (!totalByCategory[category]) {
+        totalByCategory[category] = {};
+      }
+      if (!totalByCategory[category][currency]) {
+        totalByCategory[category][currency] = 0;
+      }
+      totalByCategory[category][currency] += amount;
+    }
+
+    return {
+      count: expenses.length,
+      totalByCurrency: Object.fromEntries(
+        Object.entries(totalByCurrency).map(([currency, total]) => [currency, total])
+      ),
+      totalByCategory: Object.fromEntries(
+        Object.entries(totalByCategory).map(([category, currencies]) => [
+          category,
+          Object.fromEntries(
+            Object.entries(currencies).map(([currency, total]) => [currency, total])
+          )
+        ])
+      )
+    };
+  };
+
+  const api = {
+    add: addExpense,
+    update: updateExpense,
+    remove: removeExpense,
+    list: listExpenses,
+    get: getExpense,
+    summary
+  };
+
+  await loadExpenses();
+
+  return freeze(api);
+}

